import {
  generateSound,
  initSoundsDir,
  clearSoundCache,
  getSoundCache,
  SoundType,
  getVariantSoundType,
} from '../../src/sounds';
import { getAudioDuration } from '../../src/audio-utils';
import { createWriteStream, existsSync, mkdirSync, unlinkSync, statSync } from 'fs';
import { pipeline } from 'stream/promises';
import { execSync } from 'child_process';

// Mock dependencies
jest.mock('elevenlabs', () => ({
  ElevenLabsClient: jest.fn().mockImplementation(() => ({
    textToSoundEffects: {
      convert: jest.fn(),
    },
  })),
}));

jest.mock('fs', () => ({
  createWriteStream: jest.fn(),
  existsSync: jest.fn(),
  mkdirSync: jest.fn(),
  unlinkSync: jest.fn(),
  statSync: jest.fn(),
}));

jest.mock('stream/promises', () => ({
  pipeline: jest.fn(),
}));

jest.mock('child_process', () => ({
  execSync: jest.fn(),
}));

jest.mock('../../src/audio-utils', () => ({
  getAudioDuration: jest.fn(),
}));

import { ElevenLabsClient } from 'elevenlabs';

describe('sounds', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    clearSoundCache();
  });

  describe('initSoundsDir', () => {
    it('should create directory if it does not exist', () => {
      (existsSync as jest.Mock).mockReturnValue(false);

      initSoundsDir('/path/to/sounds');

      expect(mkdirSync).toHaveBeenCalledWith('/path/to/sounds', { recursive: true });
    });

    it('should not create directory if it already exists', () => {
      (existsSync as jest.Mock).mockReturnValue(true);

      initSoundsDir('/path/to/sounds');

      expect(mkdirSync).not.toHaveBeenCalled();
    });
  });

  describe('generateSound', () => {
    const mockAudioStream = { pipe: jest.fn() };
    const mockWriteStream = { on: jest.fn() };

    beforeEach(() => {
      (existsSync as jest.Mock).mockReturnValue(false);
      (createWriteStream as jest.Mock).mockReturnValue(mockWriteStream);
      (pipeline as jest.Mock).mockResolvedValue(undefined);
      (getAudioDuration as jest.Mock).mockResolvedValue(100);
      (execSync as jest.Mock).mockReturnValue(undefined);
      (unlinkSync as jest.Mock).mockReturnValue(undefined);
      // Default to valid file size (>1000 bytes)
      (statSync as jest.Mock).mockReturnValue({ size: 2000 });
    });

    it('should throw error if sounds directory not initialized', async () => {
      // Cache is cleared in beforeEach, so soundsDir is null
      await expect(generateSound('click')).rejects.toThrow(
        'Sounds directory not initialized. Call initSoundsDir() first.'
      );
    });

    it('should generate click sound with correct prompt', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      expect(mockConvert).toHaveBeenCalledWith({
        text: 'MacBook Pro trackpad click, soft satisfying tap, ASMR quality, no background noise, isolated sound',
        duration_seconds: 0.5,
      });
    });

    it('should generate keypress sound with correct prompt', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('keypress');

      expect(mockConvert).toHaveBeenCalledWith({
        text: 'ASMR keyboard key press, satisfying soft thock, MacBook scissor switch, no background noise, isolated sound',
        duration_seconds: 0.5,
      });
    });

    it('should generate keypress-letter-1 sound with correct prompt', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('keypress-letter-1');

      expect(mockConvert).toHaveBeenCalledWith({
        text: 'ASMR keyboard key press, soft satisfying thock, gentle attack, MacBook style, no background noise, isolated sound',
        duration_seconds: 0.5,
      });
    });

    it('should generate keypress-space-1 sound with correct prompt', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('keypress-space-1');

      expect(mockConvert).toHaveBeenCalledWith({
        text: 'ASMR spacebar press, satisfying deep thock, resonant, MacBook style, no background noise, isolated sound',
        duration_seconds: 0.5,
      });
    });

    it('should generate keypress-return sound with correct prompt', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('keypress-return');

      expect(mockConvert).toHaveBeenCalledWith({
        text: 'ASMR enter key press, satisfying thock, slightly longer decay, MacBook style, no background noise, isolated sound',
        duration_seconds: 0.5,
      });
    });

    it('should write audio to temp path before trimming', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      // Audio is first written to temp path, then ffmpeg trims it
      expect(createWriteStream).toHaveBeenCalledWith('/tmp/sounds/click.temp.mp3');
    });

    it('should return result with correct path and duration', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);
      (getAudioDuration as jest.Mock).mockResolvedValue(150);

      const result = await generateSound('click');

      expect(result).toEqual({
        path: '/tmp/sounds/click.mp3',
        durationMs: 150,
      });
    });

    it('should cache sound result and not regenerate', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);
      (getAudioDuration as jest.Mock).mockResolvedValue(100);

      // First call
      const result1 = await generateSound('click');
      // Second call - should use cache
      const result2 = await generateSound('click');

      expect(mockConvert).toHaveBeenCalledTimes(1);
      expect(result1).toEqual(result2);
    });

    it('should load from disk if file exists and is valid', async () => {
      initSoundsDir('/tmp/sounds');
      // File exists on disk
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds') return true;
        if (path === '/tmp/sounds/click.mp3') return true;
        return false;
      });
      // File is valid (>1000 bytes)
      (statSync as jest.Mock).mockReturnValue({ size: 2000 });
      (getAudioDuration as jest.Mock).mockResolvedValue(200);

      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      const result = await generateSound('click');

      // Should not call API
      expect(mockConvert).not.toHaveBeenCalled();
      expect(result).toEqual({
        path: '/tmp/sounds/click.mp3',
        durationMs: 200,
      });
    });

    it('should cache result after loading from disk', async () => {
      initSoundsDir('/tmp/sounds');
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds') return true;
        if (path === '/tmp/sounds/keypress.mp3') return true;
        return false;
      });
      // File is valid (>1000 bytes)
      (statSync as jest.Mock).mockReturnValue({ size: 2000 });
      (getAudioDuration as jest.Mock).mockResolvedValue(50);

      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // First call - loads from disk
      await generateSound('keypress');

      // Clear the existsSync mock for the second call check
      (existsSync as jest.Mock).mockReturnValue(false);

      // Second call - should use memory cache
      const result = await generateSound('keypress');

      expect(mockConvert).not.toHaveBeenCalled();
      expect(getAudioDuration).toHaveBeenCalledTimes(1); // Only called once
      expect(result.durationMs).toBe(50);
    });

    it('should handle API error', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockRejectedValue(new Error('API rate limit'));
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await expect(generateSound('click')).rejects.toThrow('API rate limit');
    });

    it('should handle pipeline error', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);
      (pipeline as jest.Mock).mockRejectedValue(new Error('Write failed'));

      await expect(generateSound('click')).rejects.toThrow('Write failed');
    });

    it('should retry when generated file is too small (silent audio)', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // First two attempts produce invalid (too small) files, third succeeds
      (statSync as jest.Mock)
        .mockReturnValueOnce({ size: 250 }) // First attempt: invalid
        .mockReturnValueOnce({ size: 250 }) // Second attempt: invalid
        .mockReturnValueOnce({ size: 2000 }); // Third attempt: valid

      // existsSync for temp file cleanup and invalid file deletion
      let existsCallCount = 0;
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        existsCallCount++;
        // Temp files exist for cleanup, output files exist for deletion on retry
        if (path.endsWith('.temp.mp3')) return true;
        if (path.endsWith('.mp3') && existsCallCount > 1) return true;
        return false;
      });

      const result = await generateSound('click');

      // Should have called API 3 times due to retries
      expect(mockConvert).toHaveBeenCalledTimes(3);
      expect(result.durationMs).toBe(100);
    });

    it('should throw error after max retries for invalid files', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // All attempts produce invalid files
      (statSync as jest.Mock).mockReturnValue({ size: 250 });

      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path.endsWith('.temp.mp3')) return true;
        if (path.endsWith('.mp3')) return true;
        return false;
      });

      await expect(generateSound('click')).rejects.toThrow(
        'Failed to generate valid sound for "click" after 3 attempts'
      );

      // Should have retried 3 times
      expect(mockConvert).toHaveBeenCalledTimes(3);
    });

    it('should regenerate if cached file on disk is invalid', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // File exists on disk but is invalid (too small)
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds') return true;
        if (path === '/tmp/sounds/click.mp3') return true;
        if (path.endsWith('.temp.mp3')) return true;
        return false;
      });

      // First check shows invalid file, after regeneration it's valid
      (statSync as jest.Mock)
        .mockReturnValueOnce({ size: 250 }) // Cached file is invalid
        .mockReturnValueOnce({ size: 2000 }); // After regeneration, valid

      const result = await generateSound('click');

      // Should have called API to regenerate
      expect(mockConvert).toHaveBeenCalledTimes(1);
      expect(result.durationMs).toBe(100);
    });

    it('should treat file as invalid if statSync throws an error', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // File exists on disk but statSync throws (file deleted between checks)
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds') return true;
        if (path === '/tmp/sounds/click.mp3') return true;
        if (path.endsWith('.temp.mp3')) return true;
        return false;
      });

      // First statSync throws error (file inaccessible), second is valid after regeneration
      (statSync as jest.Mock)
        .mockImplementationOnce(() => { throw new Error('ENOENT'); }) // Cached file check fails
        .mockReturnValueOnce({ size: 2000 }); // After regeneration, valid

      const result = await generateSound('click');

      // Should have called API to regenerate because statSync threw
      expect(mockConvert).toHaveBeenCalledTimes(1);
      expect(result.durationMs).toBe(100);
    });

    it('should call ffmpeg with silenceremove filter', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      expect(execSync).toHaveBeenCalledWith(
        expect.stringContaining('silenceremove=start_periods=1:start_threshold=-30dB'),
        expect.any(Object)
      );
    });

    it('should call ffmpeg with the exact fade-out start derived from the target duration', async () => {
      // Kills L165:26 ArithmeticOperator: fadeOutStart = TARGET (0.1) * 0.7 = 0.07.
      // The `/ 0.7` mutant would produce ~0.142857, so we pin the literal `st=0.07`.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      // The afade filter must use the multiplied (not divided) start time.
      // 0.1 * 0.7 === 0.06999999999999999; the `/ 0.7` mutant gives ~0.1428.
      expect(execSync).toHaveBeenCalledWith(
        expect.stringContaining('afade=t=out:st=0.06999999999999999:'),
        expect.any(Object)
      );
    });

    it('should call ffmpeg with the exact fade-out duration derived from the target duration', async () => {
      // Kills L166:29 ArithmeticOperator: fadeOutDuration = TARGET (0.1) * 0.3 = 0.03.
      // The `/ 0.3` mutant would produce ~0.333, so we pin the literal `d=...0.03`.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      // The afade filter must use the multiplied (not divided) duration.
      // 0.1 * 0.3 === 0.03; the `/ 0.3` mutant gives ~0.3333.
      expect(execSync).toHaveBeenCalledWith(
        expect.stringContaining('d=0.03"'),
        expect.any(Object)
      );
    });

    it('should call ffmpeg with stdio set to pipe', async () => {
      // Kills L169:7 ObjectLiteral: the execSync options must be { stdio: 'pipe' }.
      // The `{}` mutant would drop the stdio option entirely.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      await generateSound('click');

      expect(execSync).toHaveBeenCalledWith(
        expect.any(String),
        { stdio: 'pipe' }
      );
    });

    it('should not delete temp file when it does not exist after trimming', async () => {
      // Kills L173:9 ConditionalExpression (-> true): cleanup of the temp file
      // is guarded by existsSync(tempPath). When the temp file does not exist,
      // unlinkSync must not be called for it. Forcing the condition to `true`
      // would call unlinkSync on the (missing) temp path.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // Nothing exists on disk: no dir, no temp file, no output file.
      // statSync still reports a valid (2000-byte) file so generation succeeds.
      (existsSync as jest.Mock).mockReturnValue(false);

      await generateSound('click');

      // Success path with no existing files: nothing should be unlinked.
      expect(unlinkSync).not.toHaveBeenCalled();
    });

    it('should delete the invalid output file before retrying when it exists', async () => {
      // Kills L183:9 ConditionalExpression (-> false) and L183:33 BlockStatement (-> {}):
      // after an invalid generation, if the output file exists it must be deleted
      // before the next retry. The `false` / empty-block mutants skip the deletion.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // statSync calls: attempt 1 post-trim validation (invalid), attempt 2 (valid).
      // The initial on-disk cache check is skipped because existsSync(outputPath)
      // is false on the first probe (see counter below).
      (statSync as jest.Mock)
        .mockReturnValueOnce({ size: 250 }) // attempt 1: invalid -> triggers delete
        .mockReturnValueOnce({ size: 2000 }); // attempt 2: valid

      // Output file: absent for the initial disk-cache probe (so we generate),
      // present for the invalid-file delete guard (so the delete branch runs).
      // Temp file never exists, so temp cleanup cannot produce a spurious
      // unlinkSync(outputPath).
      let mp3Probes = 0;
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds/click.mp3') {
          mp3Probes++;
          return mp3Probes > 1; // false on first (disk-cache), true thereafter
        }
        return false;
      });

      await generateSound('click');

      // The invalid output file must have been deleted before retrying.
      expect(unlinkSync).toHaveBeenCalledWith('/tmp/sounds/click.mp3');
    });

    it('should not delete the output file on retry when it does not exist', async () => {
      // Kills L183:9 ConditionalExpression (-> true): the invalid-file delete is
      // guarded by existsSync(outputPath). When the output file does not exist,
      // unlinkSync must not be called for it. Forcing the condition to `true`
      // would unlink the (missing) output path.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // First attempt invalid, second attempt valid.
      (statSync as jest.Mock)
        .mockReturnValueOnce({ size: 250 }) // attempt 1: invalid
        .mockReturnValueOnce({ size: 2000 }); // attempt 2: valid

      // Neither temp nor output file ever exists on disk.
      (existsSync as jest.Mock).mockReturnValue(false);

      await generateSound('click');

      // No file existed, so nothing should be unlinked across the retry.
      expect(unlinkSync).not.toHaveBeenCalled();
    });

    it('should treat a file exactly at the minimum valid size as valid', async () => {
      // Kills L115:12 EqualityOperator (>= -> >): MIN_VALID_FILE_SIZE is 1000.
      // A 1000-byte cached file on disk must be considered valid (>=), so the
      // API is NOT called. The `>` mutant would treat 1000 as invalid and regenerate.
      initSoundsDir('/tmp/sounds');
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path === '/tmp/sounds') return true;
        if (path === '/tmp/sounds/click.mp3') return true;
        return false;
      });
      // Exactly at the boundary.
      (statSync as jest.Mock).mockReturnValue({ size: 1000 });
      (getAudioDuration as jest.Mock).mockResolvedValue(123);

      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      const result = await generateSound('click');

      // Boundary file is valid -> loaded from disk, no API call.
      expect(mockConvert).not.toHaveBeenCalled();
      expect(result.durationMs).toBe(123);
    });

    it('should throw the exact failure message after max retries', async () => {
      // Kills L190:9 StringLiteral (-> ``): the thrown Error message must contain
      // the full descriptive text. The empty-template mutant would throw an empty message.
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // Every attempt produces an invalid (too-small) file.
      (statSync as jest.Mock).mockReturnValue({ size: 250 });
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path.endsWith('.temp.mp3')) return true;
        if (path.endsWith('.mp3')) return true;
        return false;
      });

      await expect(generateSound('click')).rejects.toThrow(
        'Failed to generate valid sound for "click" after 3 attempts. ' +
          'ElevenLabs may be generating silent audio for this prompt.'
      );
    });

    it('should clean up temp file after trimming', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue(mockAudioStream);
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);

      // Temp file exists after generation
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        if (path.endsWith('.temp.mp3')) return true;
        return false;
      });

      await generateSound('click');

      expect(unlinkSync).toHaveBeenCalledWith('/tmp/sounds/click.temp.mp3');
    });
  });

  describe('clearSoundCache', () => {
    it('should clear the cache', async () => {
      initSoundsDir('/tmp/sounds');
      const mockConvert = jest.fn().mockResolvedValue({ pipe: jest.fn() });
      const mockClient = {
        textToSoundEffects: {
          convert: mockConvert,
        },
      };
      (ElevenLabsClient as jest.Mock).mockImplementation(() => mockClient);
      (existsSync as jest.Mock).mockImplementation((path: string) => {
        // Temp file exists for cleanup
        if (path.endsWith('.temp.mp3')) return true;
        return false;
      });
      (createWriteStream as jest.Mock).mockReturnValue({ on: jest.fn() });
      (pipeline as jest.Mock).mockResolvedValue(undefined);
      (getAudioDuration as jest.Mock).mockResolvedValue(100);
      (execSync as jest.Mock).mockReturnValue(undefined);
      (unlinkSync as jest.Mock).mockReturnValue(undefined);
      (statSync as jest.Mock).mockReturnValue({ size: 2000 });

      // Generate a sound
      await generateSound('click');
      expect(getSoundCache().size).toBe(1);

      // Clear cache
      clearSoundCache();
      expect(getSoundCache().size).toBe(0);
    });

    it('should reset soundsDir to null', async () => {
      initSoundsDir('/tmp/sounds');
      clearSoundCache();

      // Should throw because soundsDir is null
      await expect(generateSound('click')).rejects.toThrow(
        'Sounds directory not initialized'
      );
    });
  });

  describe('getSoundCache', () => {
    it('should return the cache map', () => {
      const cache = getSoundCache();
      expect(cache).toBeInstanceOf(Map);
    });
  });

  describe('getVariantSoundType', () => {
    it('should return a valid keypress-letter variant', () => {
      const result = getVariantSoundType('keypress-letter');
      expect(result).toMatch(/^keypress-letter-[1-5]$/);
    });

    it('should return a valid keypress-space variant', () => {
      const result = getVariantSoundType('keypress-space');
      expect(result).toMatch(/^keypress-space-[1-5]$/);
    });

    it('should avoid immediate repetition for keypress-letter', () => {
      // Call multiple times and track results
      const results: string[] = [];
      for (let i = 0; i < 20; i++) {
        results.push(getVariantSoundType('keypress-letter'));
      }

      // Check that no two consecutive results are the same
      for (let i = 1; i < results.length; i++) {
        expect(results[i]).not.toBe(results[i - 1]);
      }
    });

    it('should avoid immediate repetition for keypress-space', () => {
      // Call multiple times and track results
      const results: string[] = [];
      for (let i = 0; i < 20; i++) {
        results.push(getVariantSoundType('keypress-space'));
      }

      // Check that no two consecutive results are the same
      for (let i = 1; i < results.length; i++) {
        expect(results[i]).not.toBe(results[i - 1]);
      }
    });

    it('should track letter and space variants independently', () => {
      // Get a letter variant
      const letter1 = getVariantSoundType('keypress-letter');
      // Get a space variant - should be independent
      const space1 = getVariantSoundType('keypress-space');
      // Get another letter variant - should avoid letter1, not space1
      const letter2 = getVariantSoundType('keypress-letter');

      expect(letter2).not.toBe(letter1);
      // space1 is independent - no assertion needed about its relationship
      expect(space1).toMatch(/^keypress-space-[1-5]$/);
    });

    it('should compute the variant index as floor(random*5)+1', () => {
      // Kills L72:15 ArithmeticOperator (+ 1 -> - 1): with Math.random mocked to 0,
      // the original computes floor(0*5)+1 = 1 -> 'keypress-letter-1'. The `- 1`
      // mutant would compute floor(0*5)-1 = -1 -> 'keypress-letter--1'.
      // isolateModules gives a fresh module so lastVariantUsed starts empty (default 0),
      // guaranteeing the do/while loop terminates deterministically for index 1.
      const randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0);

      let result: string | undefined;
      jest.isolateModules(() => {
        const fresh = require('../../src/sounds');
        result = fresh.getVariantSoundType('keypress-letter');
      });

      expect(result).toBe('keypress-letter-1');

      randomSpy.mockRestore();
    });

    it('should compute the highest variant index from a near-1 random value', () => {
      // Reinforces L72:15: Math.random ~0.99 -> floor(0.99*5)+1 = 5 (original),
      // while the `- 1` mutant would yield floor(0.99*5)-1 = 3.
      // Fresh module => lastVariantUsed default 0, so index 5 is accepted immediately.
      const randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0.99);

      let result: string | undefined;
      jest.isolateModules(() => {
        const fresh = require('../../src/sounds');
        result = fresh.getVariantSoundType('keypress-space');
      });

      expect(result).toBe('keypress-space-5');

      randomSpy.mockRestore();
    });

    it('should return all variants over many calls (statistical)', () => {
      const letterVariants = new Set<string>();
      const spaceVariants = new Set<string>();

      // Run enough times to likely get all variants
      for (let i = 0; i < 100; i++) {
        letterVariants.add(getVariantSoundType('keypress-letter'));
        spaceVariants.add(getVariantSoundType('keypress-space'));
      }

      // Should have gotten all 5 letter variants
      expect(letterVariants.size).toBe(5);
      // Should have gotten all 5 space variants
      expect(spaceVariants.size).toBe(5);
    });
  });
});

